using System;using System.IO;using System.Diagnostics;using System.Security.Principal;using System.Security.Cryptography;using System.Threading;using System.Reflection;
// PRIVATE qualification only. This binary cannot address DeviceInstall policy.
internal static class UsbExactBlockSystemQualification {
 static string StateRoot{get{return Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,"State");}}
 static string stage="entry";
 static void Check(bool b){if(!b)throw new InvalidOperationException("Private SYSTEM qualification refused");}
 static string Hash(string path){using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant();}
 static UsbExactBlockState.Request Request(string action,UsbExactBlockState.Snapshot before,string[] ids,string[] targets){var now=DateTime.UtcNow;return new UsbExactBlockState.Request(action,before,new UsbExactBlockState.Snapshot(before==null?1:before.Generation+1,WindowsIdentity.GetCurrent().User.Value,ids),targets,Guid.NewGuid().ToString("N"),new string('a',64),now,now.AddMinutes(5));}
 static int Recovery(string nonce,string digest){Check(WindowsIdentity.GetCurrent().User.Value=="S-1-5-18");string image=Assembly.GetExecutingAssembly().Location;Check(image==Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,UsbExactBlockRecoveryTasks.ImageName(Hash(image))));
  using(var store=new UsbExactBlockFileStore(StateRoot)){var pending=store.ReadPending();Check(pending!=null&&pending.Request.Nonce==nonce&&pending.Request.Digest==digest);var r=pending.Request;var decision=store.ClaimRecovery(digest);var backend=new UsbExactBlockNativeBackendQualification.ManualPrivateBackend(store,nonce);if(UsbExactBlockState.Same(decision,r.Before))backend.RestoreBefore(r);else Check(UsbExactBlockState.Same(decision,r.After));backend.VerifyPolicy(decision);return 0;}
 }
 static void DispatchAndWait(UsbExactBlockState.Request r){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));scheduler.Connect();dynamic folder=scheduler.GetFolder("\\");dynamic task=folder.GetTask(UsbExactBlockRecoveryTasks.TaskName(r.Nonce));DateTime before=(DateTime)task.LastRunTime;task.Run(null);var timer=Stopwatch.StartNew();while(timer.Elapsed.TotalSeconds<175){Thread.Sleep(200);task=folder.GetTask(UsbExactBlockRecoveryTasks.TaskName(r.Nonce));if((DateTime)task.LastRunTime>before&&(int)task.State!=4&&(int)task.State!=2){Check((int)task.LastTaskResult==0);return;}}throw new TimeoutException("Private SYSTEM recovery timeout");}
 static void RecoverPrevious(UsbExactBlockFileStore store){var pending=store.ReadPending();if(pending==null)return;var r=pending.Request;Check(r.Before==null&&store.ReadCommitted()==null&&r.Action=="block"&&r.Targets.Length==1&&r.Targets[0]==@"USB\VID_0001&PID_0001&MI_00\PRIVATE_A");dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();dynamic task=service.GetFolder("\\").GetTask(UsbExactBlockRecoveryTasks.TaskName(r.Nonce));string path=(string)task.Definition.Actions[1].Path;string name=Path.GetFileName(path);Check(name.StartsWith("exact-recovery-",StringComparison.Ordinal)&&name.EndsWith(".exe",StringComparison.Ordinal));string hash=name.Substring(15,name.Length-19);Check(path==Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,UsbExactBlockRecoveryTasks.ImageName(hash)));using(var tasks=new UsbExactBlockRecoveryTasks(store,hash)){var backend=new UsbExactBlockNativeBackendQualification.ManualPrivateBackend(store,r.Nonce);Check(UsbExactBlockState.Same(store.ClaimRecovery(r.Digest),r.Before));backend.RestoreBefore(r);backend.VerifyPolicy(null);tasks.Retire(r,()=>backend.VerifyPolicy(null));store.RetirePending(r.Digest);backend.DeleteEmptyProbe();Console.WriteLine("PASS prior private fixture recovered and authenticated task retired");}}
 static int Inspect(){Check(new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator));using(var store=new UsbExactBlockFileStore(StateRoot)){var p=store.ReadPending();Console.WriteLine("private_pending="+(p==null?"absent":p.Phase.ToString())+" committed="+(store.ReadCommitted()==null?"absent":"present"));if(p==null)return 0;dynamic service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));service.Connect();try{dynamic task=service.GetFolder("\\").GetTask(UsbExactBlockRecoveryTasks.TaskName(p.Request.Nonce));dynamic d=task.Definition;Console.WriteLine("task_present=true enabled="+task.Enabled+" state="+task.State+" limit="+d.Settings.ExecutionTimeLimit+" trigger_count="+d.Triggers.Count+" directory_matches="+((string)d.Actions[1].WorkingDirectory==UsbExactBlockRecoveryTasks.CodeRoot));foreach(dynamic trigger in d.Triggers)Console.WriteLine("trigger_type="+trigger.Type+" interval="+trigger.Repetition.Interval+" duration="+trigger.Repetition.Duration);Console.WriteLine("principal="+d.Principal.UserId+" acl="+task.GetSecurityDescriptor(7));}catch(System.Runtime.InteropServices.COMException e){Console.WriteLine("private_task_read_code="+e.HResult.ToString("X8"));}}return 0;}
 [STAThread]static int Main(string[] args){try{if(args.Length==1&&args[0]=="--inspect-private")return Inspect();if(args.Length==3&&args[0]=="recover"){DuckyWorkerJob.AttachCurrentWorker();return Recovery(args[1],args[2]);}if(args.Length!=1||args[0]!="--private-system")return 2;Check(new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator));DuckyWorkerJob.AttachCurrentWorker();stage="provision-code";SentinelPolicyDirectory.Provision(UsbExactBlockRecoveryTasks.CodeRoot);stage="pin-code";using(var codePin=new UsbExactBlockFileStore(UsbExactBlockRecoveryTasks.CodeRoot)){string self=Assembly.GetExecutingAssembly().Location,hash=Hash(self),installed=Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,UsbExactBlockRecoveryTasks.ImageName(hash));if(!File.Exists(installed)){File.Copy(self,installed);var acl=new System.Security.AccessControl.FileSecurity();acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})acl.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule(new SecurityIdentifier(sid,null),System.Security.AccessControl.FileSystemRights.FullControl,System.Security.AccessControl.AccessControlType.Allow));File.SetAccessControl(installed,acl);}Check(Hash(installed)==hash);stage="provision-state";SentinelPolicyDirectory.Provision(StateRoot);
  stage="open-state";using(var store=new UsbExactBlockFileStore(StateRoot)){stage="recover-prior";RecoverPrevious(store);stage="verify-empty";Check(store.ReadPending()==null&&store.ReadCommitted()==null);string a=@"USB\VID_0001&PID_0001&MI_00\PRIVATE_A";var r=Request("block",null,new[]{a},new[]{a});stage="prepare";store.WritePrepared(r);stage="pin-worker";using(var tasks=new UsbExactBlockRecoveryTasks(store,hash)){stage="arm-task";tasks.Arm(r);tasks.VerifyArmed(r);store.AdvancePending(r.Digest,UsbExactBlockState.Stage.Prepared,UsbExactBlockState.Stage.RecoveryArmed);var backend=new UsbExactBlockNativeBackendQualification.ManualPrivateBackend(store,r.Nonce);stage="apply-private";backend.ApplyCandidate(r);store.AdvancePending(r.Digest,UsbExactBlockState.Stage.RecoveryArmed,UsbExactBlockState.Stage.Applied);stage="dispatch-recovery";DispatchAndWait(r);Check(store.ReadPending().Phase==UsbExactBlockState.Stage.RecoveryClaimed&&store.ReadCommitted()==null);backend.VerifyPolicy(null);tasks.Retire(r,()=>backend.VerifyPolicy(null));store.RetirePending(r.Digest);backend.DeleteEmptyProbe();Console.WriteLine("PASS actual SYSTEM task restores uncommitted private policy and external controller verifies retirement; no device or reboot acceptance");return 0;}}}
 }catch(Exception e){Console.WriteLine("FAIL private SYSTEM qualification stage="+stage+" category="+e.GetType().Name+" code="+e.HResult.ToString("X8")+" method="+(e.TargetSite==null?"unknown":e.TargetSite.Name));return 1;}}
}
